def mark_existing_awards_approved(apps, schema_editor):
    """Pre-existing AwardDecision rows were direct awards: mark them APPROVED."""

    AwardDecision = apps.get_model("sourcing", "AwardDecision")

    for decision in AwardDecision.objects.all():

        decision.status = "APPROVED"

        decision.recommended_by_id = decision.recommended_by_id or decision.approved_by_id

        decision.decided_at = decision.decided_at or decision.updated_at

        decision.save(update_fields=["status", "recommended_by", "decided_at"])


